          <label class="choice"><input type="checkbox" name="q3" value="PHP"><span>PHP</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Swift"><span>Swift</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="TypeScript"><span>TypeScript</span></label>
