       .quiz-card {
         padding: 20px;
       }

       .form-field {
         padding: 16px;
       }
     }
   </style>
 </head>
 <body>
   <main class="quiz-card">
     <h1>Computer Languages Quiz</h1>
     <p class="subtitle">Choose all answers that apply for each question.</p>

     <form id="quiz-form">
       <div class="form-field">
         <p class="question">1. Which of these are programming languages?</p>
         <p class="help-text">Select every option that is used to write software.</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="HTML"><span>HTML</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q1" value="CSS"><span>CSS</span></label>
         </div>
       </div>

       <div class="form-field">
         <p class="question">2. Which of these are compiled languages?</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q2" value="C"><span>C</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Rust"><span>Rust</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Ruby"><span>Ruby</span></label>
           <label class="choice"><input type="checkbox" name="q2" value="Go"><span>Go</span></label>
         </div>
       </div>

       <div class="form-field">
         <p class="question">3. Which of these are used in web development?</p>
         <div class="choices">
           <label class="choice"><input type="checkbox" name="q3" value="JavaScript"><span>JavaScript</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="PHP"><span>PHP</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="Swift"><span>Swift</span></label>
           <label class="choice"><input type="checkbox" name="q3" value="TypeScript"><span>TypeScript</span></label>
         </div>
       </div>

       <div class="actions">
         <button type="submit">Submit Quiz</button>
       </div>
       <div class="result" id="result" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById("quiz-form");
     const result = document.getElementById("result");

     const answers = {
       q1: ["Python", "JavaScript"],
       q2: ["C", "Rust", "Go"],
       q3: ["JavaScript", "PHP", "TypeScript"]
     };

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const score = Object.keys(answers).reduce((total, key) => {
         const selected = [...form.querySelectorAll(`input[name="${key}"]:checked`)].map((input) => input.value);
         const correct = answers[key];
         const isMatch =
           selected.length === correct.length &&
           selected.every((value) => correct.includes(value));
         return total + (isMatch ? 1 : 0);
       }, 0);

       result.textContent = `You got ${score} out of 3 questions correct.`;
     });
   </script>
 </body>
 </html>

')
